import { HttpContextToken, HttpInterceptorFn } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';

// The date this user's screen shows the sheet as of (yyyy-mm-dd), or null for as it stands now. It belongs to the
// screen: other users are unaffected.
@Injectable({ providedIn: 'root' })
export class AsOf {
  readonly date = signal<string | null>(null);
}

// Marks a request answered as the sheet stands now, whatever date the screen shows it as of.
export const LIVE = new HttpContextToken<boolean>(() => false);

// Sends the as-of date with every request (but one marked LIVE), so the server answers as of it and refuses every
// change.
export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
  const date = req.context.get(LIVE) ? null : inject(AsOf).date();
  return next(date ? req.clone({ setHeaders: { 'X-As-Of': date } }) : req);
};
import { HttpClient } from '@angular/common/http';
import { ApplicationRef, Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { AsOf } from './as-of';
import { UserColumns } from './columns';
import { UserLocale } from './locale';

// Who is signed in and which sheet is active. Everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);
  private readonly appRef = inject(ApplicationRef);
  private readonly asOf = inject(AsOf);
  private readonly userLocale = inject(UserLocale);
  private readonly userColumns = inject(UserColumns);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  // The active sheet's today (yyyy-mm-dd): every date decision and default date uses it.
  readonly sheetToday = signal<string | null>(null);
  // Whether the active sheet is archived: it stays visible and every change on it is refused.
  readonly sheetArchived = signal(false);
  // The number of the active sheet's last bulk settle batch, or null when there has been none.
  readonly sheetLastBatch = signal<number | null>(null);
  // Counts sheet loads, so a view re-reads the store even when the same id is loaded again.
  readonly loads = signal(0);
  // The date the screen shows the sheet as of, or null: while set, every figure is as the sheet stood at the end of
  // it, the date stands in for the sheet's today, and every change is refused.
  readonly sheetAsOf = this.asOf.date.asReadonly();

  async signIn(name: string): Promise<void> {
    const u = await firstValueFrom(this.http.post<{ name: string }>('/api/signin', { name }));
    await this.userLocale.load();
    await this.userColumns.load();
    this.user.set(u.name);
  }

  async loadSheet(id: string): Promise<void> {
    const s = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}`, null),
    );
    this.sheetId.set(s.id);
    this.sheetToday.set(s.today);
    this.sheetArchived.set(s.archived);
    this.sheetLastBatch.set(s.lastBatch);
    this.loads.update((n) => n + 1);
  }

  // Shows the sheet as of the date (null: as it stands now), re-read from the store.
  async setAsOf(date: string | null): Promise<void> {
    this.asOf.date.set(date);
    const id = this.sheetId();
    if (id) await this.loadSheet(id);
  }

  // Resolves once the screen has re-read everything it asked the store for (after a sheet load or a new as-of date,
  // say), so what is taken from it then shows the sheet as it is loaded.
  async settled(): Promise<void> {
    do {
      await this.appRef.whenStable();
      // a request answered may lead a view to ask for more
      await new Promise((resolve) => setTimeout(resolve));
    } while (!(await firstValueFrom(this.appRef.isStable)));
  }

  async setToday(today: string): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    const s = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }),
    );
    this.sheetToday.set(s.today);
  }

  // Clones the active sheet to another id, never used before.
  async cloneSheet(toSheetId: string): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    await firstValueFrom(this.http.post(`/api/sheets/${encodeURIComponent(id)}/clone`, { toSheetId }));
  }

  async archive(): Promise<void> {
    const id = this.sheetId();
    if (!id) return;
    const s = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null),
    );
    this.sheetArchived.set(s.archived);
  }
}

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  lastBatch: number | null;
}
import { Component, inject, signal } from '@angular/core';
import { FigPipe } from '../../core/locale';
import { Session } from '../../core/session';
import { LOCALES, UserLocale } from '../../core/locale';
import { People } from '../people/people';
import { Rates } from '../rates/rates';
import { Settings, SettingsStore } from '../settings/settings';
import { Grades } from '../grades/grades';
import { Delegation } from '../delegation/delegation';
import { Holidays } from '../holidays/holidays';
import { VoidReasons } from '../void-reasons/void-reasons';
import { Notes } from '../notes/notes';
import { ClaimTemplates } from '../claim-templates/claim-templates';
import { Pools } from '../pools/pools';
import { Crews } from '../crews/crews';
import { AuditViewer } from '../audit-viewer/audit-viewer';
import { TreeSearch } from '../tree-search/tree-search';
import { Duplicates } from '../duplicates/duplicates';
import { PlanStore } from '../plans/plans';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [FigPipe, People, Rates, Settings, Grades, Delegation, Holidays, VoidReasons, Notes, ClaimTemplates, Pools, Crews, TreeSearch, Duplicates, AuditViewer],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user | fig }}</strong></p>

      <form (submit)="saveLocale($event)" aria-label="Your locale">
        <label for="user-locale">Locale</label>
        <select id="user-locale" data-testid="user-locale" (change)="localeInput.set(value($event)); localeError.set(null)">
          @for (l of locales; track l) {
            <option [value]="l" [selected]="l === (localeInput() ?? userLocale.locale())">{{ l }}</option>
          }
        </select>
        <button type="submit" data-testid="user-locale-save">Save locale</button>
        <span>Current: <strong data-testid="user-locale-current">{{ userLocale.locale() }}</strong></span>
        @if (localeError(); as err) {
          <p role="alert" data-testid="user-locale-error">{{ err }}</p>
        }
      </form>

      <form (submit)="load($event)" aria-label="Load sheet">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetInput()"
          (input)="sheetInput.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-load-error">{{ err | fig }}</p>
        }
      </form>

      @if (session.sheetId(); as id) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ id | fig }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ session.sheetToday() | fig }}</strong></p>
        <p>Archived: <strong data-testid="sheet-archived">{{ (session.sheetArchived() ? 'yes' : 'no') | fig }}</strong></p>
        <p>Parent sheet: <strong data-testid="sheet-parent">{{ (settings.parent() ?? '') | fig }}</strong></p>

        <form (submit)="saveToday($event)" aria-label="Change today">
          <label for="sheet-today">New today</label>
          <input
            id="sheet-today"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>

        <form (submit)="cloneSheet($event)" aria-label="Clone sheet">
          <label for="sheet-clone-to">Clone to sheet id</label>
          <input
            id="sheet-clone-to"
            data-testid="sheet-clone-to"
            [value]="cloneInput()"
            (input)="cloneInput.set(value($event)); todayError.set(null)"
          />
          <button type="submit" data-testid="sheet-clone">Clone sheet</button>
        </form>
        <p>Cloned to: <strong data-testid="sheet-cloned-to">{{ (clonedTo() ?? '') | fig }}</strong></p>

        <p>As of: <strong data-testid="sheet-asof">{{ (session.sheetAsOf() ?? '') | fig }}</strong></p>
        <form (submit)="setAsOf($event)" aria-label="Show the sheet as of a date">
          <label for="asof-date">Show as of</label>
          <input
            id="asof-date"
            type="date"
            data-testid="asof-date"
            [value]="asOfInput()"
            (input)="asOfInput.set(value($event)); asOfError.set(null)"
          />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          @if (asOfError(); as err) {
            <p role="alert" data-testid="asof-error">{{ err | fig }}</p>
          }
        </form>
        @if (todayError(); as err) {
          <p role="alert" data-testid="sheet-error">{{ err | fig }}</p>
        }

        <app-rates />
        <app-settings />
        <app-grades />
        <app-delegation />
        <app-holidays />
        <app-void-reasons />
        <app-notes />
        <app-claim-templates />
        <app-people />
        <app-pools />
        <app-crews />
        <app-tree-search />
        <app-duplicates />
        <app-audit-viewer />
      }
